"use client";

import { Waveform as WaveformPrimitive } from "@audio-ui/react";
import { cn } from "@/lib/utils";
import type { WaveformBar } from "@/lib/waveform-path";

const DEFAULT_VIEW_BOX = "0 0 800 100";

interface WaveformProps extends WaveformPrimitive.RootProps {
  bars: WaveformBar[];
  variant?: "default" | "playhead";
  viewBox?: string;
}

export function Waveform({
  bars,
  className,
  variant = "default",
  viewBox = DEFAULT_VIEW_BOX,
  ...props
}: WaveformProps) {
  return (
    <WaveformPrimitive.Root
      className="w-full min-w-0 data-[disabled=true]:cursor-not-allowed"
      {...props}
    >
      <WaveformPrimitive.Track
        className={cn(
          "relative h-20 rounded-none border bg-card relative w-full min-w-0 cursor-pointer touch-none select-none overflow-hidden py-1",
          "focus-within:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          className
        )}
        data-slot="waveform"
      >
        <WaveformPrimitive.Svg
          className="[-webkit-mask-image:linear-gradient(to_right,transparent,black_16px,black_calc(100%-16px),transparent)] mask-[linear-gradient(to_right,transparent,black_16px,black_calc(100%-16px),transparent)]"
          viewBox={viewBox}
        >
          <WaveformPrimitive.Bars bars={bars} className="pointer-events-none fill-border [rx:0]" />
          <WaveformPrimitive.BarsProgress
            bars={bars}
            className="pointer-events-none fill-primary [rx:0]"
          />
        </WaveformPrimitive.Svg>
        {variant === "playhead" && (
          <>
            <WaveformPrimitive.Playhead className="inset-y-0 w-0.5 -translate-x-1/2 bg-primary" />
            <WaveformPrimitive.Thumb className="inset-y-0 my-auto size-3.5 rounded-sm border-2 border-background bg-primary shadow-md" />
          </>
        )}
      </WaveformPrimitive.Track>
    </WaveformPrimitive.Root>
  );
}
